from collections import Counter


def transform(grid):
    h, w = len(grid), len(grid[0])
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]

    # The 2-colored full-length line is the divider. Extend a parallel 8-line
    # just beyond the object on the side opposite the divider.
    orientation = None
    divider = None
    for r in range(h):
        if all(grid[r][c] == 2 for c in range(w)):
            orientation, divider = "horizontal", r
            break
    if orientation is None:
        for c in range(w):
            if all(grid[r][c] == 2 for r in range(h)):
                orientation, divider = "vertical", c
                break
    if orientation is None:
        return out

    if orientation == "vertical":
        coords = [c for r in range(h) for c in range(w)
                  if grid[r][c] not in (background, 2)]
        if not coords:
            return out
        center = sum(coords) / len(coords)
        if center > divider:
            target = max(coords) + 1
        elif center < divider:
            target = min(coords) - 1
        else:
            return out
        if 0 <= target < w:
            for r in range(h):
                out[r][target] = 8
    else:
        coords = [r for r in range(h) for c in range(w)
                  if grid[r][c] not in (background, 2)]
        if not coords:
            return out
        center = sum(coords) / len(coords)
        if center > divider:
            target = max(coords) + 1
        elif center < divider:
            target = min(coords) - 1
        else:
            return out
        if 0 <= target < h:
            for c in range(w):
                out[target][c] = 8
    return out
